/* Ronda 2 · NEG-BELL · datos de las 32 subcategorías de servicios (06–36 y 40, sin la 37–39, que son tiendas) que no hizo la ronda 1.
   Cada una: nombres (10), secciones, servicios completos, quién los atiende, textos «Acerca de», preguntas frecuentes y horarios.
   Todo es ficticio; sin marcas reales; sin consejos médicos (Belleza no es Salud). Textos «es | en». */
export const S = (sec, es, en, de, dn, p, d, o = {}) => ({ sec, es, en, de, dn, p, d, buf: o.buf ?? 5, from: !!o.from, extra: !!o.extra, core: !!o.core, dep: o.dep ?? 0 });

